pub type Result<T> = StdResult<T, Error>;

#[derive(Debug)]
pub struct Error {
    issue: &'static str,
    fault: ErrorFault,
    solution: &'static str,
}

#[derive(Debug)]
pub enum ErrorFault {
    Code(Option<String>),
    User,
    File,
}

fn assert(assertion: bool, issue: &'static str, solution: &'static str, fault: ErrorFault) -> Result<()> {
    if assertion {
        Result::Ok(())
    } else {
        Result::Err(Error { issue, fault, solution })
    }
}

type V3 = Vector<f32>;

pub async fn main(model: Arc<Model>, sender: mpsc::UnboundedSender<DisplayCommand>, receiver: mpsc::UnboundedReceiver<ProcessorCommand>) {
    let mut processor = Processor::new(sender, receiver, model);
    
    processor.run().await;
}

struct Processor {
    sender: mpsc::UnboundedSender<DisplayCommand>,
    receiver: mpsc::UnboundedReceiver<ProcessorCommand>,
    model: Arc<Model>,
    vertex_to_faces: Vec<Vec<usize>>
}

#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Connectivity {
    OnVertex(usize),
    /// Not to be used manually, as it leads to duplicates if the usizes are swapped.
    OnEdge(usize, usize)
}

impl Connectivity {
    fn on_edge(a: usize, b: usize) -> Self {
        let (a, b) = if a >= b {
            (a, b)
        } else {
            (b, a)
        };
        Self::OnEdge(a, b)
    }
}

#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Node {
    connectivity: Connectivity,
    pos: PVec3,
}

pub enum ProcessorCommand {
    MouseDownOnPoint {
        face_index: usize,
        position: V3,
        button: MouseButton
    }
}

#[derive(Clone, Copy)]
enum Group {
    Seed,
    Dijkstras,
    IsolinePoints,
    IsolineConnectors,
    IsolinePruned,
    ReverseTraverse,
    Backtrack
}

struct GeneratedInfo {
    nodes: HashMap<Node, (f32, Option<Node>)>,
    stitch_size: f32,
    epsilon: f32,
    seed_point: PVec3,
    seed_face: usize,
}

impl Processor {
    fn new(sender: mpsc::UnboundedSender<DisplayCommand>, receiver: mpsc::UnboundedReceiver<ProcessorCommand>, model: Arc<Model>) -> Self {
        let mut vertex_to_faces: Vec<Vec<usize>> = std::iter::repeat_with(Vec::new).take(model.mesh.vertices.len()).collect();
        for (i, face) in model.mesh.faces.iter().enumerate() {
            for vertex in face.vertices {
                vertex_to_faces[vertex].push(i)
            }
        }
        vertex_to_faces.shrink_to_fit();
        Self { sender, receiver, model, vertex_to_faces }
    }

    async fn run(&mut self) {
        let mut info = None;
        // self.generate_from_seed(Vector::<f32>::new([52.76231, 66.21611, 26.4832]), 56).await;
        while let Some(ProcessorCommand::MouseDownOnPoint { face_index, position, button }) = self.receiver.recv().await {
            match button {
                MouseButton::Left => {
                    let (nodes, stitch_size, epsilon) = self.generate_from_seed(position, face_index).await.unwrap();
                    info = Some(GeneratedInfo { nodes, stitch_size, epsilon, seed_point: position.into(), seed_face: face_index });
                },
                MouseButton::Right => if let Some(info) = &info { self.reverse_traverse(info, position, face_index) },
                MouseButton::Middle => (),
            }
        }
    }

    async fn generate_from_seed(&self, position: Vector<f32>, face_index: usize) -> Result<(HashMap<Node, (f32, Option<Node>)>, f32, f32)> {
        const STITCH_SIZE_EPSILON_MULTIPLIER: f32 = 0.25;
        
        self.sender.send(DisplayCommand::ClearAll).unwrap();
        self.sender.send(DisplayCommand::Point { pos: position, radius: self.model.radius * 0.02, colour: Srgba::BLUE, depth: true, group: Group::Seed as usize }).unwrap();
        let stitch_size = self.model.radius / 14.0;
        let epsilon = stitch_size * STITCH_SIZE_EPSILON_MULTIPLIER;
        let (nodes, furthest_point) = self.dijkstras(epsilon, position.into(), face_index);
        let furthest_len = nodes.get(&furthest_point).unwrap().0;
        let len = nodes.len();
        println!("Diameter: {}; furthest_len: {furthest_len:?}", self.model.radius * 2.0);
        for (node, (geo_len, _pre)) in &nodes {
            // tokio::time::sleep(Duration::from_secs_f32(6.0 / len as f32)).await;
            self.sender.send(
                DisplayCommand::Point {
                    pos: node.pos.into(),
                    radius: self.model.radius * 0.007,
                    colour: hsv(3.0 * geo_len / furthest_len, 1.0, 1.0),
                    depth: true,
                    group: Group::Dijkstras as usize
                    
                }).unwrap()
            }
        
        let (isolines, furthest_point) = self.isolines(&nodes, furthest_len, furthest_point, stitch_size, stitch_size * STITCH_SIZE_EPSILON_MULTIPLIER)?;

        let info = GeneratedInfo { nodes, stitch_size, epsilon, seed_point: position.into(), seed_face: face_index };

        println!("{}", self.connect(&info, &isolines, furthest_point)?.heirarchy());
        Ok((info.nodes, stitch_size, epsilon))
    }

    fn get_connected_faces(&self, v1: usize, v2: usize) -> Vec<usize> {
        let mut faces1 = self.vertex_to_faces[v1].clone();
        let faces2 = &self.vertex_to_faces[v2];
        faces1.retain(|face| faces2.contains(face));
        faces1
    }

    fn edges_on_face(&self, face: usize) -> [[usize; 2]; 3] {
        let v = self.model.mesh.faces[face].vertices;
        [[v[0], v[1]], [v[1], v[2]], [v[2], v[0]]]
    }

    fn node_into_on_edge(&self, node: Node) -> NodeOnEdge {
        match node.connectivity {
            Connectivity::OnVertex(a) => NodeOnEdge {
                edge: OnEdge::new(a, *self.model.mesh.faces[self.vertex_to_faces[a][0]].vertices.iter().find(|v| **v != a).unwrap()),
                pos: node.pos
            },
            Connectivity::OnEdge(a, b) => NodeOnEdge { edge: OnEdge { a, b }, pos: node.pos },
        }
    }
}

fn remove_duplicates<T: PartialEq>(vec: Vec<T>) -> Vec<T> {
    let mut new = Vec::new();
    for item in vec {
        if !new.contains(&item) {
            new.push(item);
        }
    }
    new
}

fn hsv(h: f32, s: f32, v: f32) -> Srgba {
    Hsva::new(h, s, v, 1.0).to_srgb().into()
}